def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    score = 0
    opp_defects = 0
    my_defects = 0
    for i, (a, b) in enumerate(history):
        if a == 'C' and b == 'C':
            score += 3
        elif a == 'C' and b == 'D':
            score += 0
        elif a == 'D' and b == 'C':
            score += 5
        else:
            score += 1
        if b == 'D':
            opp_defects += 1
        if a == 'D':
            my_defects += 1

    last_mine, last_opp = history[-1]

    if n < 10:
        if last_opp == 'D':
            return 'D'
        return 'C'

    recent = history[-10:]
    opp_recent_defects = sum(1 for _, b in recent if b == 'D')
    my_recent_defects = sum(1 for a, _ in recent if a == 'D')

    if opp_recent_defects == 0:
        return 'C'

    if opp_recent_defects >= 7:
        return 'D'

    if last_opp == 'D':
        if last_mine == 'D':
            return 'D' if rng.random() < 0.7 else 'C'
        return 'D'

    if last_opp == 'C':
        if last_mine == 'D':
            return 'C'
        return 'C'

    return 'C'
